"goals": [
  {
    "id": "first-survey",
    "title": "A supported first survey",
    "mode": "achievement",
    "rows": [
      "east",
      "west"
    ],
    "requirement": "Earn a real beacon observation with the actual initially blank survey-camera at survey-window, through one local rigid clear watertight surface enclosing that camera’s own lens and plate. This first service may later move.",
    "conditions": [
      {
        "kind": "object",
        "label": "actual survey camera observed beacon through its rigid clear boundary",
        "place": "survey-window",
        "initialKey": "survey-camera",
        "record": {
          "subject": "place:beacon",
          "viewpoint": "survey-window",
          "throughSurface": true,
          "fromInitial": "survey-camera"
        },
        "hasSurface": {
          "traits": {
            "rigidity": "rigid",
            "optical": "clear",
            "permeability": "watertight"
          },
          "enclosesOrigin": {
            "key": "survey-camera",
            "kinds": [
              "lens",
              "record-plate"
            ]
          }
        }
      }
    ]
  },
  {
    "id": "working-soft-filter",
    "title": "A soft form doing real work",
    "mode": "achievement",
    "rows": [
      "east",
      "west"
    ],
    "requirement": "The actual original working-clay material matches filter-pad’s profile, fits while moldable, and actively supplies its outgoing water route to the growing nursery at garden. The displayed outlet supplies water only through an actively seated exposed porous matching surface; hand water remains available for wetting clay. This is an operating temporary filter, not a fit demonstration; it may later be fired and repurposed.",
    "conditions": [
      {
        "kind": "surface",
        "label": "original soft fitted material actively supplies water",
        "place": "filter-pad",
        "initialKey": "working-clay",
        "test": {
          "originKey": "working-clay",
          "traits": {
            "rigidity": "moldable",
            "permeability": "porous"
          },
          "fitted": {
            "place": "filter-pad",
            "rigidity": "moldable"
          },
          "contact": "filter-pad",
          "supplying": "water"
        }
      },
      {
        "kind": "link",
        "label": "the original soft filter actively feeds the original nursery",
        "channel": "water",
        "fromPlace": "filter-pad",
        "toPlace": "garden",
        "fromInitial": "working-clay",
        "toInitial": "nursery",
        "active": true,
        "fromSurface": {
          "originKey": "working-clay",
          "traits": {
            "rigidity": "moldable",
            "permeability": "porous"
          },
          "fitted": {
            "place": "filter-pad",
            "rigidity": "moldable"
          },
          "contact": "filter-pad",
          "supplying": "water"
        }
      },
      {
        "kind": "object",
        "label": "the actual nursery grows using that service",
        "place": "garden",
        "initialKey": "nursery",
        "properties": {
          "growing": true
        }
      }
    ]
  },
  {
    "id": "living-station",
    "title": "Keep the living station working",
    "rows": [
      "east",
      "west"
    ],
    "requirement": "At the endpoint the actual nursery at garden grows in both sky rows inside one active rigid clear watertight local boundary enclosing its original tray and seed. Familiar lamps, real reflected light and whole assembly copies remain legal.",
    "conditions": [
      {
        "kind": "object",
        "label": "same original nursery grows within its local clear rigid boundary",
        "place": "garden",
        "initialKey": "nursery",
        "hasSurface": {
          "traits": {
            "rigidity": "rigid",
            "optical": "clear",
            "permeability": "watertight"
          },
          "enclosesOrigin": {
            "key": "nursery",
            "kinds": [
              "tray",
              "seed"
            ]
          },
          "growing": true
        }
      }
    ]
  },
